import{_ as r,o as e,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Construction-Operator.md","filePath":"manual-zh/Matrix-Construction-Operator.md","lastUpdated":1785684581000}'),d={name:"manual-zh/Matrix-Construction-Operator.md"};function c(n,t,i,s,h,p){return e(),a("div",null,[...t[0]||(t[0]=[o('<h4 id="_16-4-1-1-matrix-construction-operator" tabindex="-1">16.4.1.1 Matrix Construction Operator <code>{}</code> <a class="header-anchor" href="#_16-4-1-1-matrix-construction-operator" aria-label="Permalink to &quot;16.4.1.1 Matrix Construction Operator `{}`&quot;">​</a></h4><p>使用 <code>{``}</code> 运算符构造矩阵。在大括号内，逗号分隔一行内的元素，分号分隔各行。以下示例展示了一个 <em>2×3</em> 矩阵、一个 <em>1×4</em> 行向量、一个 <em>3×1</em> 列向量和一个标量。</p><table tabindex="0"><thead><tr><th>{1, 2, 3; 4, 5, 6}</th><th>⇒</th><th>[1 2 3] [4 5 6]</th></tr></thead><tbody><tr><td>{3.14, 6.28, 9.24, 12.57}</td><td>⇒</td><td>[3.14 6.28 9.42 12.57]</td></tr><tr><td>{1.41; 1.73; 2}</td><td>⇒</td><td>[1.41] [1.73] [2.00]</td></tr><tr><td>{5}</td><td>⇒</td><td>5</td></tr></tbody></table><p>花括号不限于容纳数值字面量。它们可以包含计算，并且可以以任何方式将矩阵和向量拼接在一起，只要结果是矩形的。例如，如果‘m’是矩阵 <code>{1, 2; 3, 4}</code>，‘r’是行向量 <code>{5, 6}</code>，而‘c’是列向量 <code>{7, 8}</code>，则花括号可以按如下方式使用：</p><table tabindex="0"><thead><tr><th>{m, c; r, 10}</th><th>⇒</th><th>[1 2 7] [3 4 8] [5 6 10]</th></tr></thead><tbody><tr><td>{c, 2 * c, T(r)}</td><td>⇒</td><td>[7 14 5] [8 16 6]</td></tr></tbody></table><p>上面的最后一个示例使用了转置函数 <code>T</code>。</p>',6)])])}const l=r(d,[["render",c]]);export{_ as __pageData,l as default};
